insert into public.works (ym, cat, title, where_text, what, pic, body) values
  ('2026-11-01', 'space', '입동, 찻자리의 꽃', '개인 다회 · 서울', '낙엽송과 마른 연밥', 'ikebana-larch', '겨울로 들어서는 날의 다회. 낮은 굽 수반에 잎을 떨구기 직전의 낙엽송 한 가지를 세우고, 찻상 끝에는 마른 연밥 하나만 두었습니다.'),
  ('2026-10-01', 'project', '갤러리 개관 꽃', '성수동 갤러리', '억새와 감나무 가지', 'ill', '흰 벽의 전시장 입구에 억새 다발과 감이 달린 가지를 세웠습니다. 전시가 끝난 뒤 가지는 말려 갤러리에 남겼어요.'),
  ('2026-09-01', 'sub', '백로의 한 줄기', '정기 구독 · 아홉 번째 꽃', '대나무와 부채 잎', 'ikebana-bamboo', '이슬이 맺히기 시작하는 때, 곧은 대나무와 접은 잎으로 서늘한 선을 보냈습니다.'),
  ('2026-07-01', 'sub', '소서, 한련 한 줄기', '정기 구독 · 일곱 번째 꽃', '한련과 한련잎', 'ikebana-nasturtium', '더위가 시작되는 때, 둥근 잎 아래 주홍 한 점을 걸어 작은 화기에 담았습니다.'),
  ('2026-06-01', 'space', '들꽃 정원의 오후', '가평 정원 촬영', '코스모스와 들풀', 'field', '정원 브랜드의 사진 촬영을 위해 들풀 사이에 꽃을 꽂아 두었습니다. 꽃은 촬영 뒤 정원에 그대로 돌려보냈어요.'),
  ('2026-04-01', 'project', '말린 꽃 상자', '출판사 행사 답례품', '말린 꽃과 감싸개', 'dried-box', '책 출간 행사의 답례로 말린 꽃 한 줄기를 상자에 담고, 감싸개로 한 번 더 쌌습니다.'),
  ('2026-03-01', 'sub', '경칩의 수선', '정기 구독 · 세 번째 꽃', '수선 한 송이', 'ikebana-daffodil', '개구리가 깨어나는 때, 노란 수선 한 송이로 봄을 먼저 알렸습니다.');
insert into public.gatherings (kind, title, date, time_text, place, capacity, seats_left, fee, fee_note, description, status, note) values
  ('꽃 모임', '입동의 수반 꽃꽂이', '2026-11-14', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 10, 3, 55000, '꽃, 화기 대여, 차, 감싸개 포함', '낮은 수반에 침봉을 놓고, 겨울로 들어서는 가지 하나와 마른 잎으로 선을 세워 봅니다. 꽂은 꽃은 감싸개에 싸서 가져가세요.', '모집 중', ''),
  ('보자기 매듭 수업', '쪽물 보자기 매듭 짓기', '2026-11-28', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 8, 8, 45000, '쪽물 들인 천, 차 포함', '쪽물 들인 천으로 감싸기와 매듭 짓기를 배웁니다.', '모집 중', ''),
  ('꽃 모임', '대설, 소나무 한 가지', '2026-12-12', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 10, 10, 55000, '꽃, 화기 대여, 차, 감싸개 포함', '눈이 많이 내린다는 대설, 소나무 한 가지로 수반 꽃꽂이를 합니다.', '모집 예정', ''),
  ('계절 찻자리', '동지 찻자리', '2026-12-21', '월요일 저녁 7시–9시', '설담화 작업실 (서울)', 6, 6, 40000, '꽃, 차 포함', '한 해 중 밤이 가장 긴 날, 찻자리에 놓을 작은 꽃을 꽂고 함께 차를 마십니다.', '모집 예정', ''),
  ('꽃 모임', '한로의 억새', '2026-10-10', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 10, 0, 55000, '', '', '마감', '억새 세 줄기를 서로 다른 높이로 세우고, 남은 잎은 말려 책갈피로 나눠 가졌어요.'),
  ('보자기 매듭 수업', '쪽물 들이기', '2026-09-26', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 8, 0, 45000, '', '', '마감', '무명 손수건을 쪽물에 세 번 담갔다 꺼내며, 같은 천도 담그는 횟수마다 빛이 달라지는 걸 보았어요.'),
  ('꽃 모임', '백로의 한 줄기', '2026-09-12', '토요일 오후 2시–4시', '설담화 작업실 (서울)', 10, 0, 55000, '', '', '마감', '이슬이 맺히기 시작하는 때라 물을 머금은 잎을 골랐어요. 차는 햇보리차를 냈습니다.');
